    function updateVisitWeekday(){const lang=document.querySelector('#language').value||'en';if(!visitDate.value){visitWeekday.textContent=weekdayEmptyText[lang]||weekdayEmptyText.en;return}const [year,month,day]=visitDate.value.split('-').map(Number);const selectedDate=new Date(Date.UTC(year,month-1,day,12));visitWeekday.textContent=new Intl.DateTimeFormat(weekdayLocales[lang]||weekdayLocales.en,{timeZone:'Asia/Kolkata',weekday:'long'}).format(selectedDate)}
    visitDate.addEventListener('input',updateVisitWeekday);updateVisitWeekday();
    document.querySelector('#distance').oninput=(event)=>{const km=Number(event.target.value)||0;document.querySelector('#charge').innerHTML=`${pageCopy[currentLanguage].charge} <b>₹${Math.ceil(Math.max(0,km-10))*20}</b>`};
    document.querySelector('#booking-form').onsubmit=async(event)=>{event.preventDefault();const form=event.currentTarget;if(!form.reportValidity())return;if(!currentAccount){notify('Sign in or create a customer account before saving this home-visit request.');auth('login');return}if(isOwnerEmail(currentAccount.email)){notify('Use a customer account to request a home visit.');return}const values=new FormData(form),distance=Number(values.get('distance')),travelCharge=Math.ceil(Math.max(0,distance-10))*20;if(!Number.isFinite(distance)||distance<0){notify('Enter a valid distance from Chhajli.');return}const submit=form.querySelector('.send-button');submit.disabled=true;submit.textContent='Saving securely…';const notes=[`Home address: ${String(values.get('address')||'').trim()}`,`Preferred weekday: ${visitWeekday.textContent}`,`Preferred date: ${values.get('visitDate')}`,`Preferred time: ${values.get('visitTime')}`,`Distance from Chhajli: ${distance} km`,`Estimated travel charge: ₹${travelCharge}`,`Customer phone: ${String(values.get('mobile')||'').trim()}`].join('\n');try{const saved=await saveCustomerRequest({name:String(values.get('name')||'').trim(),mobile:String(values.get('mobile')||'').trim(),email:currentAccount.email,service:'Home visit · '+String(values.get('service')||''),notes,files:[],storeFiles:false});notify(requestSavedMessage(saved));form.reset();visitDate.min=chhajliToday();updateVisitWeekday();document.querySelector('#charge').innerHTML=`${pageCopy[currentLanguage].charge} <b>₹0</b>`}catch(error){notify(error.message)}finally{submit.disabled=false;submit.innerHTML=`${pageCopy[currentLanguage].book} <span>↗</span>`}};
