    Object.assign(pageCopy.pa,{footerContact:'WhatsApp Business +91 79866 30948 ↗',privacyText:'ਅਪਲੋਡ ਕੀਤੇ ਦਸਤਾਵੇਜ਼ ਸਿਰਫ਼ ਚੁਣੀ ਸੇਵਾ ਲਈ ਵਰਤੇ ਜਾਣ। ਅਸਲ ਦਸਤਾਵੇਜ਼ ਆਨਲਾਈਨ ਲੈਣ ਤੋਂ ਪਹਿਲਾਂ ਸੁਰੱਖਿਅਤ ਸਟੋਰੇਜ ਅਤੇ ਮਿਟਾਉਣ ਦੇ ਨਿਯਮ ਤਿਆਰ ਕਰਨੇ ਲਾਜ਼ਮੀ ਹਨ।'});
    Object.assign(pageCopy.hi,{footerContact:'WhatsApp Business +91 79866 30948 ↗',privacyText:'अपलोड किए दस्तावेज़ केवल चुनी गई सेवा के लिए उपयोग करें। असली दस्तावेज़ ऑनलाइन लेने से पहले सुरक्षित स्टोरेज और हटाने के नियम तैयार होने चाहिए।'});
    Object.assign(pageCopy.en,{nav:['Customer corner','Documents','Punjab news','Home service'],aboutText:'Punjab CSC is a neighborhood digital service point in Chhajli, Sunam. We help customers understand document checklists, prepare online applications, scan and upload files, explore public notices, and request home visits. We explain steps and charges before work begins. Government decisions, eligibility, official fees, and deadlines remain with the authority.',clockLabel:'Punjab time',opportunityTag:'PUNJAB PUBLIC UPDATES',opportunityHead:'Jobs, scholarships and schemes.',opportunityIntro:'Follow official portals for current openings, eligibility and deadlines. We do not mark an old notice as open; check the source before applying.',opportunityLabels:['Recruitment','PSSSB · PPSC','Scholarships','Schemes · citizen services'],opportunityTitles:['Punjab Government jobs','Board and commission ads','Student support','Punjab e-services'],opportunityTexts:['Browse state recruitment notices and confirm post details, documents and last date at the issuing department.','Check the latest Punjab recruitment advertisements, corrections, exam notices and result updates.','Check state and national scholarship portals for eligible students, required proofs and application windows.','Open official citizen service portals for scheme information, certificates and current online services.'],opportunityLinks:['Open Punjab recruitment notices ↗','PSSSB official site ↗','PPSC official site ↗','Punjab scholarship portal ↗','National Scholarship Portal ↗','Punjab eSewa ↗','Punjab eServices ↗','Government notifications ↗'],opportunityFine:'Punjab CSC is an independent assistance service, not a government department. Notices, eligibility and deadlines are controlled by the official source linked on each card.',reviewTag:'CUSTOMER FEEDBACK',reviewHead:'Had a good visit?',reviewIntro:'Share an honest review of your experience. Five stars are welcome, but please choose the rating that reflects your visit.',reviewTrust:'✦  Reviews are sent to Punjab CSC for review; none are published automatically.',reviewName:'Your name',reviewRating:'Your rating',reviewBody:'Your review',reviewMin:'At least 50 words',reviewSendConsent:'I agree to send this feedback to Punjab CSC on WhatsApp for review.',reviewPublishConsent:'You may contact me to ask permission before any public display.',reviewSubmit:'Send feedback on WhatsApp',reviewCount:(count)=>`${count} / 50 words`,reviewShort:'Please write at least 50 words before sending your review.'});
    Object.assign(pageCopy.pa,{nav:['ਗਾਹਕ ਕੋਨਾ','ਦਸਤਾਵੇਜ਼','ਪੰਜਾਬ ਖ਼ਬਰਾਂ','ਘਰ ਸੇਵਾ'],aboutText:'Punjab CSC ਛਾਜਲੀ, ਸੁਨਾਮ ਵਿੱਚ ਇੱਕ ਸਥਾਨਕ ਡਿਜ਼ਿਟਲ ਸੇਵਾ ਕੇਂਦਰ ਹੈ। ਅਸੀਂ ਦਸਤਾਵੇਜ਼ਾਂ ਦੀ ਸੂਚੀ ਸਮਝਣ, ਆਨਲਾਈਨ ਅਰਜ਼ੀਆਂ ਤਿਆਰ ਕਰਨ, ਫਾਈਲਾਂ ਸਕੈਨ ਅਤੇ ਅੱਪਲੋਡ ਕਰਨ, ਸਰਕਾਰੀ ਸੂਚਨਾਵਾਂ ਵੇਖਣ ਅਤੇ ਘਰ ਆਉਣ ਦੀ ਬੇਨਤੀ ਕਰਨ ਵਿੱਚ ਮਦਦ ਕਰਦੇ ਹਾਂ। ਕੰਮ ਤੋਂ ਪਹਿਲਾਂ ਕਦਮ ਅਤੇ ਫੀਸ ਸਮਝਾਈ ਜਾਂਦੀ ਹੈ। ਅੰਤਿਮ ਫੈਸਲੇ, ਯੋਗਤਾ ਅਤੇ ਸਰਕਾਰੀ ਫੀਸ ਸੰਬੰਧਿਤ ਅਥਾਰਟੀ ਦੇ ਅਧੀਨ ਹਨ।',clockLabel:'ਪੰਜਾਬ ਦਾ ਸਮਾਂ',opportunityTag:'ਪੰਜਾਬ ਦੀਆਂ ਸਰਕਾਰੀ ਜਾਣਕਾਰੀਆਂ',opportunityHead:'ਨੌਕਰੀਆਂ, ਵਜ਼ੀਫ਼ੇ ਅਤੇ ਸਕੀਮਾਂ।',opportunityIntro:'ਨਵੀਆਂ ਅਸਾਮੀਆਂ, ਯੋਗਤਾ ਅਤੇ ਆਖ਼ਰੀ ਤਰੀਕ ਲਈ ਸਰਕਾਰੀ ਪੋਰਟਲ ਵੇਖੋ। ਪੁਰਾਣੇ ਨੋਟਿਸ ਨੂੰ ਖੁੱਲ੍ਹਾ ਨਹੀਂ ਦਿਖਾਉਂਦੇ; ਅਰਜ਼ੀ ਤੋਂ ਪਹਿਲਾਂ ਸਰੋਤ ਪੱਕਾ ਕਰੋ।',opportunityLabels:['ਭਰਤੀ','PSSSB · PPSC','ਵਜ਼ੀਫ਼ੇ','ਸਕੀਮਾਂ · ਨਾਗਰਿਕ ਸੇਵਾਵਾਂ'],opportunityTitles:['ਪੰਜਾਬ ਸਰਕਾਰ ਦੀਆਂ ਨੌਕਰੀਆਂ','ਬੋਰਡ ਅਤੇ ਕਮਿਸ਼ਨ ਦੇ ਇਸ਼ਤਿਹਾਰ','ਵਿਦਿਆਰਥੀ ਸਹਾਇਤਾ','ਪੰਜਾਬ ਈ-ਸੇਵਾਵਾਂ'],opportunityTexts:['ਸਰਕਾਰੀ ਭਰਤੀ ਨੋਟਿਸ ਵੇਖੋ ਅਤੇ ਅਸਾਮੀ, ਕਾਗਜ਼ ਤੇ ਆਖ਼ਰੀ ਤਰੀਕ ਵਿਭਾਗ ਤੋਂ ਪੱਕੀ ਕਰੋ।','ਪੰਜਾਬ ਦੀਆਂ ਭਰਤੀ ਸੂਚਨਾਵਾਂ, ਸੋਧਾਂ, ਪ੍ਰੀਖਿਆ ਨੋਟਿਸ ਅਤੇ ਨਤੀਜੇ ਵੇਖੋ।','ਯੋਗ ਵਿਦਿਆਰਥੀਆਂ ਲਈ ਵਜ਼ੀਫ਼ੇ, ਲੋੜੀਂਦੇ ਕਾਗਜ਼ ਅਤੇ ਅਰਜ਼ੀ ਸਮਾਂ ਵੇਖੋ।','ਸਕੀਮਾਂ, ਸਰਟੀਫਿਕੇਟ ਅਤੇ ਮੌਜੂਦਾ ਆਨਲਾਈਨ ਸੇਵਾਵਾਂ ਲਈ ਸਰਕਾਰੀ ਪੋਰਟਲ ਖੋਲ੍ਹੋ।'],opportunityLinks:['ਪੰਜਾਬ ਭਰਤੀ ਨੋਟਿਸ ↗','PSSSB ਸਰਕਾਰੀ ਸਾਈਟ ↗','PPSC ਸਰਕਾਰੀ ਸਾਈਟ ↗','ਪੰਜਾਬ ਵਜ਼ੀਫ਼ਾ ਪੋਰਟਲ ↗','ਰਾਸ਼ਟਰੀ ਵਜ਼ੀਫ਼ਾ ਪੋਰਟਲ ↗','ਪੰਜਾਬ eSewa ↗','ਪੰਜਾਬ eServices ↗','ਸਰਕਾਰੀ ਨੋਟੀਫਿਕੇਸ਼ਨ ↗'],opportunityFine:'Punjab CSC ਸੁਤੰਤਰ ਸਹਾਇਤਾ ਸੇਵਾ ਹੈ, ਸਰਕਾਰੀ ਵਿਭਾਗ ਨਹੀਂ। ਹਰ ਕਾਰਡ ਦਾ ਲਿੰਕ ਅਸਲ ਸਰਕਾਰੀ ਸਰੋਤ ਹੈ; ਯੋਗਤਾ ਅਤੇ ਤਰੀਕਾਂ ਉੱਥੇ ਪੱਕੀਆਂ ਕਰੋ।',reviewTag:'ਗਾਹਕਾਂ ਦੀ ਰਾਏ',reviewHead:'ਤੁਹਾਡਾ ਤਜਰਬਾ ਚੰਗਾ ਰਿਹਾ?',reviewIntro:'ਆਪਣੇ ਤਜਰਬੇ ਬਾਰੇ ਸੱਚੀ ਰਾਏ ਦਿਓ। ਪੰਜ ਸਿਤਾਰੇ ਵੀ ਦੇ ਸਕਦੇ ਹੋ, ਪਰ ਆਪਣੇ ਦੌਰੇ ਅਨੁਸਾਰ ਦਰਜਾ ਚੁਣੋ।',reviewTrust:'✦  ਰਾਏ ਪਹਿਲਾਂ Punjab CSC ਨੂੰ ਜਾਂਦੀ ਹੈ; ਕੋਈ ਰਾਏ ਆਪਣੇ ਆਪ ਪ੍ਰਕਾਸ਼ਿਤ ਨਹੀਂ ਹੁੰਦੀ।',reviewName:'ਤੁਹਾਡਾ ਨਾਮ',reviewRating:'ਤੁਹਾਡੀ ਰੇਟਿੰਗ',reviewBody:'ਤੁਹਾਡੀ ਰਾਏ',reviewMin:'ਘੱਟੋ-ਘੱਟ 50 ਸ਼ਬਦ',reviewSendConsent:'ਮੈਂ ਇਹ ਰਾਏ ਆਪਣੇ ਨਿੱਜੀ Punjab CSC ਖਾਤੇ ਵਿੱਚ ਜਾਂਚ ਲਈ ਸੰਭਾਲਣ ਲਈ ਸਹਿਮਤ ਹਾਂ।',reviewPublishConsent:'ਕਿਸੇ ਵੀ ਜਨਤਕ ਪ੍ਰਦਰਸ਼ਨ ਤੋਂ ਪਹਿਲਾਂ ਇਜਾਜ਼ਤ ਪੁੱਛਣ ਲਈ ਮੇਰੇ ਨਾਲ ਸੰਪਰਕ ਕਰ ਸਕਦੇ ਹੋ।',reviewSubmit:'ਵੈੱਬਸਾਈਟ ਤੇ ਰਾਏ ਸੰਭਾਲੋ',reviewCount:(count)=>`${count} / 50 ਸ਼ਬਦ`,reviewShort:'ਰਾਏ ਭੇਜਣ ਲਈ ਘੱਟੋ-ਘੱਟ 50 ਸ਼ਬਦ ਲਿਖੋ।'});
    Object.assign(pageCopy.hi,{nav:['ग्राहक सहायता','दस्तावेज़','पंजाब समाचार','घर सेवा'],aboutText:'Punjab CSC छाजली, सुनाम में एक स्थानीय डिजिटल सेवा केंद्र है। हम दस्तावेज़ सूची समझने, ऑनलाइन आवेदन तैयार करने, फाइलें स्कैन और अपलोड करने, सरकारी सूचनाएँ देखने और घर आने का अनुरोध करने में मदद करते हैं। काम से पहले चरण और शुल्क समझाए जाते हैं। अंतिम निर्णय, पात्रता और सरकारी शुल्क संबंधित प्राधिकरण के अधीन हैं।',clockLabel:'पंजाब का समय',opportunityTag:'पंजाब की सार्वजनिक सूचनाएँ',opportunityHead:'नौकरियाँ, छात्रवृत्तियाँ और योजनाएँ।',opportunityIntro:'नई भर्ती, पात्रता और अंतिम तारीख के लिए आधिकारिक पोर्टल देखें। पुराना नोटिस खुला नहीं दिखाते; आवेदन से पहले स्रोत जाँचें।',opportunityLabels:['भर्ती','PSSSB · PPSC','छात्रवृत्ति','योजनाएँ · नागरिक सेवाएँ'],opportunityTitles:['पंजाब सरकार की नौकरियाँ','बोर्ड और आयोग विज्ञापन','विद्यार्थी सहायता','पंजाब ई-सेवाएँ'],opportunityTexts:['सरकारी भर्ती सूचनाएँ देखें और पद, दस्तावेज़ तथा अंतिम तारीख विभाग से जाँचें।','पंजाब की भर्ती विज्ञप्तियाँ, संशोधन, परीक्षा सूचनाएँ और परिणाम देखें।','पात्र विद्यार्थियों के लिए छात्रवृत्ति, जरूरी दस्तावेज़ और आवेदन समय देखें।','योजनाओं, प्रमाणपत्र और वर्तमान ऑनलाइन सेवाओं के लिए सरकारी पोर्टल खोलें।'],opportunityLinks:['पंजाब भर्ती सूचनाएँ ↗','PSSSB आधिकारिक साइट ↗','PPSC आधिकारिक साइट ↗','पंजाब छात्रवृत्ति पोर्टल ↗','राष्ट्रीय छात्रवृत्ति पोर्टल ↗','पंजाब eSewa ↗','पंजाब eServices ↗','सरकारी सूचनाएँ ↗'],opportunityFine:'Punjab CSC स्वतंत्र सहायता सेवा है, सरकारी विभाग नहीं। हर कार्ड का लिंक आधिकारिक स्रोत है; पात्रता और तारीख वहीं जाँचें।',reviewTag:'ग्राहक प्रतिक्रिया',reviewHead:'क्या आपका अनुभव अच्छा रहा?',reviewIntro:'अपने अनुभव की सच्ची समीक्षा साझा करें। पाँच सितारे दे सकते हैं, पर वही रेटिंग चुनें जो आपके अनुभव को बताती है।',reviewTrust:'✦  समीक्षा पहले Punjab CSC को जाती है; कोई समीक्षा अपने आप प्रकाशित नहीं होती।',reviewName:'आपका नाम',reviewRating:'आपकी रेटिंग',reviewBody:'आपकी समीक्षा',reviewMin:'कम से कम 50 शब्द',reviewSendConsent:'मैं इस समीक्षा को निजी Punjab CSC खाते में जाँच के लिए सेव करने के लिए सहमत हूँ।',reviewPublishConsent:'किसी भी सार्वजनिक प्रदर्शन से पहले अनुमति पूछने के लिए आप मुझसे संपर्क कर सकते हैं।',reviewSubmit:'वेबसाइट पर समीक्षा सेव करें',reviewCount:(count)=>`${count} / 50 शब्द`,reviewShort:'समीक्षा भेजने से पहले कम से कम 50 शब्द लिखें।'});
